INSERT INTO `document_drafts` VALUES (292188236715921408,292187385024745472,291933444022210560,'未命名文档','# 新文档\n## 1\n### 2\n#### 3\n\n- [X] a\n- [ ]','2026-03-17 14:51:44.236730','2026-03-17 15:39:25.800144',NULL),(292198080818712576,292171943329665024,291933444022210560,'test','# 新文档\n1\n','2026-03-17 15:30:51.245725','2026-03-17 19:30:48.405113',NULL),(308955977237925888,308955860292341760,291887637436829696,'1','# 新文档\n## 你好\n\n','2026-05-02 21:20:45.106255','2026-05-03 11:31:37.838602',NULL),(309173284627288064,308955874884325376,291887637436829696,'未命名文档','# 新文档\n','2026-05-03 11:44:15.218423','2026-05-03 11:44:15.218423',NULL),(309195402278604800,309195304807174144,291887637436829696,'test1','# 新文档\n\n\n![微信图片_20260331123240_56_94](/api/public/doc-images/358490d8d70e44c3aff1bda2e39bf691.png)\n\n\n\n','2026-05-03 13:12:08.477390','2026-05-10 21:23:12.195826',NULL),(309197764288319488,309195304807174144,291933444022210560,'test1','# 新文档\n\n\n![微信图片_20260331123240_56_94](/api/public/doc-images/d5d6fc64f9c545ada45defd924597eb8.png)\n\n','2026-05-03 13:21:31.624670','2026-05-03 13:29:03.430952',NULL),(311843912262094848,311843799364014080,291887637436829696,'期中项目','## 通用功能\n- [ ] 用户注册\n- [ ] 用户登录\n- [ ] 权限控制（至少区分普通用户和管理员）\n- [ ] API接口文档\n## 核心功能\n- [ ] 文档管理：树形目录管理文档，支持Markdown编辑器。\n- [ ] 版本历史：保存文档的修改历史，支持版本对比和回滚。\n- [ ] 全文检索：集成Elasticsearch或使用数据库LIKE实现简单的标题/内容搜索。\n- [ ] 文档权限：可设置文档的查看/编辑权限（公开、部门可见、私有）。\n## Redis缓存应用\n- [ ] 缓存热门/最新文档：将“最近更新”和“最多阅读”的文档列表缓存。\n- [ ] 文档内容缓存：将已发布的文档最终渲染内容（HTML）缓存，极大提升访问速度。\n- [ ] 用户编辑锁：用户开始编辑文档时，在Redis设置一个editing:docId的键，防止多人同时编辑产生覆盖，编辑完成或离开页面时释放。','2026-05-10 20:36:22.470619','2026-05-10 20:42:50.236068',NULL),(311850593876447232,311850475467051008,900000000000000001,'期中项目清单','## 通用功能\n- [ ] 用户注册\n- [ ] 用户登录\n- [ ] 权限控制（至少区分普通用户和管理员）\n- [ ] API接口文档\n## 核心功能\n- [ ] 文档管理：树形目录管理文档，支持Markdown编辑器。\n- [ ] 版本历史：保存文档的修改历史，支持版本对比和回滚。\n- [ ] 全文检索：集成Elasticsearch或使用数据库LIKE实现简单的标题/内容搜索。\n- [ ] 文档权限：可设置文档的查看/编辑权限（公开、部门可见、私有）。\n## Redis缓存应用\n- [ ] 缓存热门/最新文档：将“最近更新”和“最多阅读”的文档列表缓存。\n- [ ] 文档内容缓存：将已发布的文档最终渲染内容（HTML）缓存，极大提升访问速度。\n- [ ] 用户编辑锁：用户开始编辑文档时，在Redis设置一个editing:docId的键，防止多人同时编辑产生覆盖，编辑完成或离开页面时释放。','2026-05-10 21:02:55.485594','2026-05-11 09:53:15.514782',NULL),(312044889284022272,309195304807174144,900000000000000001,'test1','# 新文档\n\n\n![微信图片_20260331123240_56_94](/api/public/doc-images/358490d8d70e44c3aff1bda2e39bf691.png)\n\n\n\n','2026-05-11 09:54:59.121161','2026-05-11 09:54:59.121161',NULL);
