INSERT INTO `document_templates` VALUES (1,'会议纪要','标准会议记录模板',NULL,1,'# 会议纪要\n\n**会议时间：** \n**会议地点：** \n**参会人员：** \n**会议主题：** \n\n## 会议内容\n\n### 讨论事项\n1. \n\n### 决议事项\n1. \n\n### 待办事项\n- [ ] \n\n## 备注\n',1,0,'会议',NULL,'2026-03-17 07:56:08','2026-03-17 07:56:08',NULL),(2,'项目计划','项目规划文档模板',NULL,1,'# 项目计划\n\n## 项目概述\n**项目名称：** \n**项目负责人：** \n**开始时间：** \n**预计完成时间：** \n\n## 项目目标\n\n## 项目范围\n\n## 里程碑\n| 阶段 | 目标 | 时间 | 负责人 |\n|------|------|------|--------|\n| | | | |\n\n## 风险评估\n\n## 资源需求\n',1,0,'项目',NULL,'2026-03-17 07:56:08','2026-03-17 07:56:08',NULL),(3,'技术文档','技术文档标准模板',NULL,1,'# 技术文档\n\n## 概述\n\n## 技术架构\n\n## 核心功能\n\n### 功能1\n**描述：** \n**实现方式：** \n\n```javascript\n// 代码示例\n```\n\n## API接口\n\n### 接口名称\n- **URL：** \n- **方法：** \n- **参数：** \n- **返回值：** \n\n## 部署说明\n\n## 常见问题\n',1,0,'技术',NULL,'2026-03-17 07:56:08','2026-03-17 07:56:08',NULL),(4,'产品需求文档','PRD标准模板',NULL,1,'# 产品需求文档 (PRD)\n\n## 文档信息\n**产品名称：** \n**版本号：** \n**创建日期：** \n**负责人：** \n\n## 需求背景\n\n## 用户画像\n\n## 功能需求\n\n### 需求1\n**优先级：** P0/P1/P2\n**描述：** \n**验收标准：** \n\n## 非功能需求\n\n## 设计稿\n\n## 时间规划\n',1,0,'产品',NULL,'2026-03-17 07:56:08','2026-03-17 07:56:08',NULL),(5,'周报模板','个人/团队周报模板',NULL,1,'# 周报 - 第X周\n\n**姓名：** \n**部门：** \n**日期：** \n\n## 本周工作总结\n\n### 完成事项\n1. \n\n### 进行中事项\n1. \n\n## 下周工作计划\n1. \n\n## 遇到的问题\n\n## 需要的支持\n',1,0,'汇报',NULL,'2026-03-17 07:56:08','2026-03-17 07:56:08',NULL);
