--
-- Table structure for table `wk_document`
--

DROP TABLE IF EXISTS `wk_document`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wk_document` (
  `doc_id` bigint NOT NULL COMMENT '文档ID',
  `parent_id` bigint DEFAULT '0' COMMENT '父文档ID',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `summary` varchar(500) DEFAULT '' COMMENT '摘要',
  `markdown_content` longtext COMMENT 'Markdown内容',
  `html_content` longtext COMMENT '渲染后的HTML',
  `visibility` varchar(20) NOT NULL DEFAULT 'public' COMMENT '可见性 public/department/private',
  `owner_id` bigint NOT NULL COMMENT '作者用户ID',
  `dept_id` bigint DEFAULT NULL COMMENT '归属部门ID',
  `status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT '状态 draft/published',
  `sort_num` int DEFAULT '0' COMMENT '排序号',
  `version_no` int NOT NULL DEFAULT '1' COMMENT '当前版本号',
  `view_count` bigint NOT NULL DEFAULT '0' COMMENT '阅读次数',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否删除',
  `published_time` datetime DEFAULT NULL COMMENT '发布时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`doc_id`),
  KEY `idx_wk_doc_parent` (`parent_id`),
  KEY `idx_wk_doc_owner` (`owner_id`),
  KEY `idx_wk_doc_dept` (`dept_id`),
  KEY `idx_wk_doc_status` (`status`),
  KEY `idx_wk_doc_visibility` (`visibility`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Wiki文档表';
/*!40101 SET character_set_client = @saved_cs_client */;

