--
-- Table structure for table `wk_document_version`
--

DROP TABLE IF EXISTS `wk_document_version`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wk_document_version` (
  `version_id` bigint NOT NULL COMMENT '版本ID',
  `doc_id` bigint NOT NULL COMMENT '文档ID',
  `version_no` int NOT NULL COMMENT '版本号',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `markdown_content` longtext COMMENT 'Markdown内容',
  `html_content` longtext COMMENT '渲染后的HTML',
  `editor_id` bigint NOT NULL COMMENT '编辑人ID',
  `editor_name` varchar(64) NOT NULL COMMENT '编辑人账号',
  `commit_message` varchar(255) DEFAULT '' COMMENT '提交说明',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`version_id`),
  KEY `idx_wk_ver_doc` (`doc_id`),
  KEY `idx_wk_ver_doc_ver` (`doc_id`,`version_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Wiki文档版本表';
